@Test
public void testThrowExceptionOnFailure() throws Exception {
    ResourceEstimator<StringRequest> failingEstimator = mock(ResourceEstimator.class);
    when(failingEstimator.estimateRequirement(any(), any())).thenThrow(new RuntimeException("Error"));
    RequestAllocatorConfig<StringRequest> configuration = RequestAllocatorConfig.builder(failingEstimator).allowParallelization().withPrioritizer(new StringRequest.StringRequestComparator()).build();
    BruteForceAllocator<StringRequest> allocator = new BruteForceAllocator<>(configuration);
    ResourcePool pool = ResourcePool.builder().maxResource(StringRequest.MEMORY, 100.).build();
    List<Requestor<StringRequest>> requests = Lists.<Requestor<StringRequest>>newArrayList(new StringRequestor("r1", "a-50", "f-50", "k-20"), new StringRequestor("r2", "j-10", "b-20", "e-20"), new StringRequestor("r3", "g-20", "c-200", "d-30"));
    Assert.expectThrows(RuntimeException.class, () -> allocator.allocateRequests(requests.iterator(), pool));
