    FileSystem fileSystem = spy(FileSystem.get(URI.create("file:///"), WriterUtils.getFsConfiguration(state)));
    FileAwareInputStreamDataWriter dataWriter = new FileAwareInputStreamDataWriter(state, fileSystem, 1, 0, null);
    FileAwareInputStream fileAwareInputStream = FileAwareInputStream.builder().file(cf).inputStream(StreamUtils.convertStream(IOUtils.toInputStream(streamString1, StandardCharsets.UTF_8))).build();
    doThrow(new AccessDeniedException("Test")).when(fileSystem).mkdirs(any());
    for (int i = 1; i <= 3; i++) {
        try {
            dataWriter.write(fileAwareInputStream);
            Assert.fail("Expected method to throw AccessDeniedException on call #" + i);
        } catch (AccessDeniedException e) {
            // expected exception
        }
    }
    doCallRealMethod().when(fileSystem).mkdirs(any());
    dataWriter.write(fileAwareInputStream);
    dataWriter.commit();
    Path writtenFilePath = new Path(new Path(state.getProp(ConfigurationKeys.WRITER_OUTPUT_DIR), cf.getDatasetAndPartition(metadata).identifier()), cf.getDestination());
    Assert.assertEquals(IOUtils.toString(new FileInputStream(writtenFilePath.toString()), StandardCharsets.UTF_8), streamString1);
}

