@Test
public void testOneNextJobToRun() throws Exception {
    String flowName = "fn";
    Dag.DagId dagId = new Dag.DagId(flowGroup, flowName, flowExecutionId);
    Dag<JobExecutionPlan> dag = DagTestUtils.buildDag("1", flowExecutionId, DagProcessingEngine.FailureOption.FINISH_ALL_POSSIBLE.name(), 2, "user5", ConfigFactory.empty().withValue(ConfigurationKeys.FLOW_GROUP_KEY, ConfigValueFactory.fromAnyRef(flowGroup)).withValue(ConfigurationKeys.FLOW_NAME_KEY, ConfigValueFactory.fromAnyRef(flowName)).withValue(ConfigurationKeys.JOB_GROUP_KEY, ConfigValueFactory.fromAnyRef(flowGroup)).withValue(ConfigurationKeys.SPECEXECUTOR_INSTANCE_URI_KEY, ConfigValueFactory.fromAnyRef(MySqlDagManagementStateStoreTest.TEST_SPEC_EXECUTOR_URI)));
    List<SpecProducer<Spec>> specProducers = getDagSpecProducers(dag);
    JobStatus jobStatus = JobStatus.builder().flowName(flowName).flowGroup(flowGroup).jobGroup(flowGroup).jobName("job0").flowExecutionId(flowExecutionId).message("Test message").eventName(ExecutionStatus.COMPLETE.name()).startTime(flowExecutionId).shouldRetry(false).orchestratedTime(flowExecutionId).build();
    dagManagementStateStore.addDag(dag);
    /*
    We cannot check the spec producers if addSpec is called on them because spec producer object changes in writing/reading
    from DMSS. So, in order to verify job submission by checking the mock invocations on spec producers, we will have to
    fix the dag, which includes SpecProducer, by mocking, when we read a dag from DMSS
    */
    doReturn(new ImmutablePair<>(Optional.of(dag.getStartNodes().get(0)), Optional.of(jobStatus))).when(dagManagementStateStore).getDagNodeWithJobStatus(any());
    doReturn(Optional.of(dag)).when(dagManagementStateStore).getDag(dagId);
    ReevaluateDagProc reEvaluateDagProc = new ReevaluateDagProc(new ReevaluateDagTask(new DagActionStore.DagAction(flowGroup, flowName, flowExecutionId, "job0", DagActionStore.DagActionType.REEVALUATE), null, dagManagementStateStore, mockedDagProcEngineMetrics), ConfigFactory.empty());
    reEvaluateDagProc.process(dagManagementStateStore, mockedDagProcEngineMetrics);
    // next job is sent to spec producer
    Mockito.verify(specProducers.get(1), Mockito.times(1)).addSpec(any());
    // there are two invocations, one after setting status and other after sending new job to specProducer
    Mockito.verify(this.dagManagementStateStore, Mockito.times(2)).updateDagNode(any());
    // assert that the first job is completed
    Assert.assertEquals(ExecutionStatus.COMPLETE, this.dagManagementStateStore.getDag(dagId).get().getStartNodes().get(0).getValue().getExecutionStatus());
    // note that only assertFalse can be tested on DagProcUtils.isDagFinished, because if it had returned true, dag must have been cleaned
    Assert.assertFalse(DagProcUtils.isDagFinished(this.dagManagementStateStore.getDag(dagId).get()));
}

