/*
    This test simulate submitting a dag with a very short job start deadline that will definitely be breached,
    resulting in the job requiring to be killed
   */
@Test
public void enforceJobStartDeadlineTest() throws Exception {
    String flowGroup = "fg";
    String flowName = "fn";
    long flowExecutionId = System.currentTimeMillis();
    MySqlDagManagementStateStore dagManagementStateStore = spy(MySqlDagManagementStateStoreTest.getDummyDMSS(this.testMetastoreDatabase));
    LaunchDagProcTest.mockDMSSCommonBehavior(dagManagementStateStore);
    DagActionStore.DagAction dagAction = new DagActionStore.DagAction(flowGroup, flowName, flowExecutionId, "job0", DagActionStore.DagActionType.ENFORCE_JOB_START_DEADLINE);
    Dag<JobExecutionPlan> dag = DagTestUtils.buildDag("1", flowExecutionId, DagProcessingEngine.FailureOption.FINISH_ALL_POSSIBLE.name(), 5, "user5", ConfigFactory.empty().withValue(ConfigurationKeys.FLOW_GROUP_KEY, ConfigValueFactory.fromAnyRef(flowGroup)).withValue(ConfigurationKeys.FLOW_NAME_KEY, ConfigValueFactory.fromAnyRef(flowName)).withValue(ConfigurationKeys.GOBBLIN_JOB_START_DEADLINE_TIME_UNIT, ConfigValueFactory.fromAnyRef(TimeUnit.MILLISECONDS.name())).withValue(ConfigurationKeys.GOBBLIN_JOB_START_DEADLINE_TIME, ConfigValueFactory.fromAnyRef(1L)).withValue(ConfigurationKeys.SPECEXECUTOR_INSTANCE_URI_KEY, ConfigValueFactory.fromAnyRef(MySqlDagManagementStateStoreTest.TEST_SPEC_EXECUTOR_URI)));
    List<SpecProducer<Spec>> specProducers = ReevaluateDagProcTest.getDagSpecProducers(dag);
    JobStatus jobStatus = JobStatus.builder().flowName(flowName).flowGroup(flowGroup).jobGroup(flowGroup).jobName("job0").flowExecutionId(flowExecutionId).message("Test message").eventName(ExecutionStatus.ORCHESTRATED.name()).startTime(flowExecutionId).shouldRetry(false).orchestratedTime(flowExecutionId).build();
    doReturn(Optional.of(dag)).when(dagManagementStateStore).getDag(any());
    doReturn(Pair.of(Optional.of(dag.getStartNodes().get(0)), Optional.of(jobStatus))).when(dagManagementStateStore).getDagNodeWithJobStatus(any());
    // simulate having a dag that has not yet started running
    dagManagementStateStore.addDag(dag);
    dagManagementStateStore.addDagAction(dagAction);
    EnforceJobStartDeadlineDagProc enforceJobStartDeadlineDagProc = new EnforceJobStartDeadlineDagProc(new EnforceJobStartDeadlineDagTask(new DagActionStore.DagAction(flowGroup, flowName, flowExecutionId, "job0", DagActionStore.DagActionType.ENFORCE_JOB_START_DEADLINE), null, dagManagementStateStore, mockedDagProcEngineMetrics), ConfigFactory.empty());
    enforceJobStartDeadlineDagProc.process(dagManagementStateStore, mockedDagProcEngineMetrics);
    // the one dag node corresponding to the EnforceStartDeadlineDagProc
    int expectedNumOfDeleteDagNodeStates = 1;
    Mockito.verify(specProducers.get(0), Mockito.times(1)).cancelJob(any(), any());
    // separately verified `specProducers.get(0)`
    specProducers.stream().skip(expectedNumOfDeleteDagNodeStates).forEach(sp -> Mockito.verify(sp, Mockito.never()).cancelJob(any(), any()));
}

