// launches the flow, submits first job, and then kills the dag.
// all the jobs are killed and first job that was already launched is killed with the job future object.
@Test
public void killDag() throws IOException, URISyntaxException, InterruptedException {
    long flowExecutionId = System.currentTimeMillis();
    Dag<JobExecutionPlan> dag = DagTestUtils.buildDag("1", flowExecutionId, DagProcessingEngine.FailureOption.FINISH_ALL_POSSIBLE.name(), 5, "user5", ConfigFactory.empty().withValue(ConfigurationKeys.FLOW_GROUP_KEY, ConfigValueFactory.fromAnyRef("fg")).withValue(ConfigurationKeys.SPECEXECUTOR_INSTANCE_URI_KEY, ConfigValueFactory.fromAnyRef(MySqlDagManagementStateStoreTest.TEST_SPEC_EXECUTOR_URI)));
    FlowCompilationValidationHelper flowCompilationValidationHelper = mock(FlowCompilationValidationHelper.class);
    doReturn(Optional.of(dag)).when(dagManagementStateStore).getDag(any());
    doReturn(com.google.common.base.Optional.of(dag)).when(flowCompilationValidationHelper).createExecutionPlanIfValid(any());
    LaunchDagProc launchDagProc = new LaunchDagProc(new LaunchDagTask(new DagActionStore.DagAction("fg", "flow1", flowExecutionId, MysqlDagActionStore.NO_JOB_NAME_DEFAULT, DagActionStore.DagActionType.LAUNCH), null, this.dagManagementStateStore, mockedDagProcEngineMetrics), flowCompilationValidationHelper, ConfigFactory.empty());
    launchDagProc.process(this.dagManagementStateStore, this.mockedDagProcEngineMetrics);
    List<SpecProducer<Spec>> specProducers = dag.getNodes().stream().map(n -> {
        try {
            return DagUtils.getSpecProducer(n);
        } catch (ExecutionException | InterruptedException e) {
            throw new RuntimeException(e);
        }
    }).collect(Collectors.toList());
    KillDagProc killDagProc = new KillDagProc(new KillDagTask(new DagActionStore.DagAction("fg", "flow1", flowExecutionId, MysqlDagActionStore.NO_JOB_NAME_DEFAULT, DagActionStore.DagActionType.KILL), null, this.dagManagementStateStore, mockedDagProcEngineMetrics), ConfigFactory.empty());
    killDagProc.process(this.dagManagementStateStore, this.mockedDagProcEngineMetrics);
    int numOfLaunchedJobs = 1;
    // all jobs in the dag
    int numOfCancelledJobs = 5;
    int numOfCancelledFlows = 1;
    int numOfCancelledJobsWithJobFuture = numOfLaunchedJobs;
    long actualCancelJobCount = specProducers.stream().mapToLong(p -> Mockito.mockingDetails(p).getInvocations().stream().filter(a -> a.getMethod().getName().equals("cancelJob")).count()).sum();
    // kill dag procs kill only the launched jobs with parameters containing jobFuture
    Mockito.verify(specProducers.get(0), Mockito.times(numOfCancelledJobsWithJobFuture)).cancelJob(any(), argThat(props -> props.getProperty(ConfigurationKeys.SPEC_PRODUCER_SERIALIZED_FUTURE, "ABSENT").equals(MockedSpecExecutor.dummySerializedFuture)));
    // job future object is not available for rest of the jobs cancel parameters
    specProducers.stream().skip(// separately verified `specProducers.get(0)` above
    numOfCancelledJobsWithJobFuture).forEach(sp -> Mockito.verify(sp, Mockito.never()).cancelJob(any(), argThat(props -> props.getProperty(ConfigurationKeys.SPEC_PRODUCER_SERIALIZED_FUTURE, "ABSENT").equals(MockedSpecExecutor.dummySerializedFuture))));
    // kill dag proc tries to cancel all the dag nodes
    Assert.assertEquals(actualCancelJobCount, numOfCancelledJobs);
    Mockito.verify(this.mockedEventSubmitter, Mockito.times(numOfCancelledJobs)).submit(eq(TimingEvent.LauncherTimings.JOB_CANCEL), anyMap());
    Mockito.verify(this.mockedEventSubmitter, Mockito.times(numOfCancelledFlows)).submit(eq(TimingEvent.FlowTimings.FLOW_CANCELLED), anyMap());
}

