        Assert.assertNotEquals(invocation.getMethod().getName(), "remove");
    }
    Assert.assertEquals(scheduler.scheduledFlowSpecs.size(), 0);
    Assert.assertEquals(schedulerService.getScheduler().getJobGroupNames().size(), 0);
}

