    HiveDataset hiveDataset = Mockito.mock(HiveDataset.class);
    Mockito.when(hiveDataset.getTable()).thenReturn(table);
    HiveCopyEntityHelper helper = Mockito.mock(HiveCopyEntityHelper.class);
